def move_between(pegs, a, b, n):
    if (len(pegs[a]) == 0):
        disc = pegs[b].pop()
        pegs[a].append(disc)
        print(f'Move disc {disc} from {b} to {a}\n')
    elif (len(pegs[b]) == 0):
        disc = pegs[a].pop()
        pegs[b].append(disc)
        print(f'Move disc {disc} from {a} to {b}\n')
    elif (pegs[a][(-1)] < pegs[b][(-1)]):
        disc = pegs[a].pop()
        pegs[b].append(disc)
        print(f'Move disc {disc} from {a} to {b}\n')
    else:
        disc = pegs[b].pop()
        pegs[a].append(disc)
        print(f'Move disc {disc} from {b} to {a}\n')
    display_board(pegs, n)

def hanoi(n, pegs):
    A = 'A'
    B = 'B'
    C = 'C'
    if ((n % 2) == 0):
        swap_values = (C, B)
        B = swap_values[0]
        C = swap_values[1]
    total_moves = ((2 ** n) - 1)
    display_board(pegs, n)
    move = 1
    while (move <= total_moves):
        if ((move % 3) == 1):
            move_between(pegs, A, C, n)
        elif ((move % 3) == 2):
            move_between(pegs, A, B, n)
        else:
            move_between(pegs, B, C, n)
        move = (move + 1)
    print('Solved!!')

